safe_mean <- function(x) {
  if (!is.numeric(x)) stop("x doit être numérique")
  if (any(!is.finite(x) & !is.na(x))) stop("Inf interdit")
  if (all(is.na(x))) return(NA_real_)
  mean(x, na.rm = TRUE)
}
safe_mean(c(10, NA, 30))
safe_mean(numeric(0))

set.seed(42)
delta <- replicate(1000, {
  mean(sample(b, length(b), replace = TRUE)) -
    mean(sample(a, length(a), replace = TRUE))
})
quantile(delta, c(0.025, 0.975))

